verify:
base = [4, 7, 8, 9, 13]
sets = [sorted(base + [x]) for x in range(14, 40)]
med = {Rational(s[2] + s[3], 2) for s in sets}
mean = {Rational(sum(s), 6) for s in sets}
rng = {s[-1] - s[0] for s in sets}
mx = {s[-1] for s in sets}
assert med == {Rational(17, 2)} and len(mean) > 1 and len(rng) > 1 and len(mx) > 1
assert choices[answer] == 'The median'
